const canvas=document.getElementById('game'),ctx=canvas.getContext('2d');
let W,H,DPR,mode='auth',lane=1,targetLane=1,distance=0,coins=0,speed=18,runCoins=0,objects=[],particles=[],trees=[],trackOffset=0;
