function resize(){DPR=Math.min(devicePixelRatio||1,2);W=innerWidth;H=innerHeight;canvas.width=W*DPR;canvas.height=H*DPR;ctx.setTransform(DPR,0,0,DPR,0,0)}addEventListener('resize',resize);resize();
function accounts(){try{return JSON.parse(localStorage.getItem('snowid_accounts')||'{}')}catch{return{}}}function saveAccounts(a){localStorage.setItem('snowid_accounts',JSON.stringify(a))}
let tab='login';document.querySelectorAll('.tab').forEach(t=>t.onclick=()=>{tab=t.dataset.tab;document.querySelectorAll('.tab').forEach(x=>x.classList.toggle('active',x===t));document.getElementById('authSubmit').textContent=tab==='login'?'ENTRER SUR LA PISTE':'CRÉER MON COMPTE';document.getElementById('password').autocomplete=tab==='login'?'current-password':'new-password'});
