document.getElementById('authForm').onsubmit=e=>{e.prevent=e.preventDefault;e.prevent();let u=document.getElementById('username').value.trim(),p=document.getElementById('password').value,a=accounts(),err=document.getElementById('error');if(u.length<2||p.length<3){err.textContent='2 caractères minimum pour le nom, 3 pour le mot.';return}if(tab==='signup'){if(a[u]){err.textContent='Ce nom de rider existe déjà.';return}a[u]={password:p,best:0};saveAccounts(a);toast('Compte créé — bienvenue !')}else{if(!a[u]||a[u].password!==p){err.textContent='Utilisateur ou mot de passe incorrect.';return}}session=u;auth.classList.add('hidden');start();};
function toast(s){let t=document.getElementById('toast');t.textContent=s;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),1800)}
function start(){mode='play';lane=1;targetLane=1;distance=0;coins=0;runCoins=0;speed=18;objects=[];particles=[];jumpY=0;vy=0;gameOver.classList.add('hidden');pausePanel.classList.add('hidden');topbar.classList.remove('hidden');controls.classList.remove('hidden');for(let i=0;i<18;i++)trees.push({side:i%2?-1:1,z:i*90+100,x:1+Math.random()*3});spawnPattern()}
function spawnPattern(){let z=900+Math.random()*260;let r=Math.random();if(r<.55){objects.push({type:Math.random()<.28?'coin':'rock',lane:Math.floor(Math.random()*3),z,r:0})}else if(r<.78){let l=Math.floor(Math.random()*3);objects.push({type:'gate',lane:l,z});objects.push({type:'gate',lane:(l+1)%3,z+180})}else{for(let i=0;i<5;i++)objects.push({type:'coin',lane:Math.floor(Math.random()*3),z:z+i*100})}}
function project(l,z){let horizon=H*.32,p=Math.max(0,1-z/1400),y=horizon+(H-horizon)*Math.pow(p,.72),scale=.15+1.15*p,roadW=W*(.18+.62*p),x=W/2+(l-1)*roadW*.34;return{x,y,scale,roadW}}
function drawMountain(){let sky=ctx.createLinearGradient(0,0,0,H*.55);sky.addColorStop(0,'#63b4cb');sky.addColorStop(.72,'#b8dde6');sky.addColorStop(1,'#eef7f7');ctx.fillStyle=sky;ctx.fillRect(0,0,W,H);ctx.fillStyle='rgba(255,255,255,.75)';ctx.beginPath();ctx.moveTo(0,H*.42);for(let i=0;i<=12;i++){let x=i*W/12,y=H*(.32+(i%3===0?.08:i%2===0?.03:.11));ctx.lineTo(x,y)}ctx.lineTo(W,H*.42);ctx.closePath();ctx.fill();}
function drawTrack(){let horizon=H*.32;ctx.beginPath();ctx.moveTo(W*.5-45,horizon);ctx.lineTo(W*.5+45,horizon);ctx.lineTo(W*.98,H);ctx.lineTo(W*.02,H);ctx.closePath();let g=ctx.createLinearGradient(0,horizon,0,H);g.addColorStop(0,'#e8f3f2');g.addColorStop(.7,'#f9fcfa');g.addColorStop(1,'#dcebea');ctx.fillStyle=g;ctx.fill();ctx.strokeStyle='rgba(92,142,151,.16)';ctx.lineWidth=2;for(let i=0;i<11;i++){let z=((i*140-trackOffset)%1540+1540)%1540;if(z<30)continue;let p=project(0,z),q=project(2,z);ctx.beginPath();ctx.moveTo(p.x,p.y);ctx.lineTo(q.x,q.y);ctx.stroke()}for(let l=0;l<=2;l++){ctx.beginPath();for(let z=20;z<1400;z+=25){let p=project(l-.5,z);if(z===20)ctx.moveTo(p.x,p.y);else ctx.lineTo(p.x,p.y)}ctx.strokeStyle='rgba(123,166,173,.13)';ctx.stroke()}}
function drawTree(t){let z=t.z-trackOffset;if(z<20||z>1450)return;let p=project(t.side>0?2.3:-.3,z);if(p.y>H*.25){ctx.save();ctx.translate(p.x,p.y);ctx.scale(p.scale,p.scale);ctx.fillStyle='#6d9c91';ctx.beginPath();ctx.moveTo(0,-95);ctx.lineTo(-38,-20);ctx.lineTo(-18,-24);ctx.lineTo(-48,4);ctx.lineTo(48,4);ctx.lineTo(18,-24);ctx.lineTo(38,-20);ctx.closePath();ctx.fill();ctx.fillStyle='#dce9e5';ctx.beginPath();ctx.moveTo(0,-95);ctx.lineTo(-24,-43);ctx.lineTo(-5,-48);ctx.lineTo(10,-70);ctx.fill();ctx.restore()}}
function drawCoin(o){let p=project(o.lane,o.z-trackOffset);if(p.y<H*.28)return;ctx.save();ctx.translate(p.x,p.y-35*p.scale);ctx.scale(p.scale,p.scale);ctx.rotate(performance.now()/450);ctx.fillStyle='#f2ca49';ctx.beginPath();ctx.ellipse(0,0,18,23,0,0,Math.PI*2);ctx.fill();ctx.lineWidth=5;ctx.strokeStyle='#fff39b';ctx.stroke();ctx.restore()}
function drawRock(o){let p=project(o.lane,o.z-trackOffset);if(p.y<H*.28)return;ctx.save();ctx.translate(p.x,p.y);ctx.scale(p.scale,p.scale);ctx.fillStyle='#71878c';ctx.beginPath();ctx.moveTo(-30,2);ctx.lineTo(-22,-30);ctx.lineTo(2,-43);ctx.lineTo(28,-25);ctx.lineTo(32,3);ctx.closePath();ctx.fill();ctx.fillStyle='#a9b7b7';ctx.beginPath();ctx.moveTo(-22,-30);ctx.lineTo(2,-43);ctx.lineTo(8,-18);ctx.closePath();ctx.fill();ctx.restore()}
function drawGate(o){let p=project(o.lane,o.z-trackOffset);if(p.y<H*.28)return;ctx.save();ctx.translate(p.x,p.y);ctx.scale(p.scale,p.scale);ctx.fillStyle='#dc6d54';ctx.fillRect(-38,-70,76,12);ctx.fillStyle='#f4a38c';ctx.fillRect(-38,-58,76,5);ctx.restore()}
function rider(){lane+=(targetLane-lane)*.16;let p=project(lane,260);ctx.save();ctx.translate(p.x,p.y-jumpY);ctx.scale(p.scale,p.scale);ctx.fillStyle='rgba(25,58,67,.16)';ctx.beginPath();ctx.ellipse(0,17,45,9,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#08131b';ctx.fillRect(-42,-5,84,10);ctx.fillStyle='#1b7f93';ctx.beginPath();ctx.roundRect(-24,-48,48,48,9);ctx.fill();ctx.fillStyle='#071422';ctx.beginPath();ctx.arc(0,-59,18,0,Math.PI*2);ctx.fill();ctx.fillStyle='#d7ff35';ctx.beginPath();ctx.arc(0,-64,14,Math.PI,Math.PI*2);ctx.fill();ctx.fillStyle='#f3bd87';ctx.beginPath();ctx.arc(8,-58,10,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#0a1a23';ctx.lineWidth=7;ctx.beginPath();ctx.moveTo(-18,-36);ctx.lineTo(-31,-10);ctx.moveTo(18,-36);ctx.lineTo(31,-10);ctx.stroke();ctx.restore()}
function update(dt){if(mode!=='play')return;distance+=speed*dt*.32;speed=Math.min(42,18+distance/220);trackOffset=(trackOffset+speed*dt*30)%1540;if(jumpY>0||vy>0){vy-=1200*dt;jumpY+=vy*dt;if(jumpY<0){jumpY=0;vy=0}}document.getElementById('coinsHud').textContent=runCoins;document.getElementById('speedHud').textContent=Math.round(speed)+' km/h';for(let o of objects){o.z-=speed*dt*30;if(o.z<320&&o.z>220&&Math.abs(o.lane-lane)<.42){if(o.type==='coin'){if(!o.done){o.done=true;runCoins++;coins++;beep(700)}}else if(jumpY<25){crash()}}}objects=objects.filter(o=>o.z>-100&&!o.done);let maxZ=objects.length?Math.max(...objects.map(o=>o.z)):0;if(maxZ<900)spawnPattern();}
function crash(){if(mode!=='play')return;mode='gameover';let a=accounts(),record=Math.floor(distance);if(record>(a[session]?.best||0)){a[session].best=record;saveAccounts(a)}document.getElementById('finalDist').textContent=record+' m';document.getElementById('finalCoins').textContent=runCoins;gameOver.classList.remove('hidden');controls.classList.add('hidden');beep(120)}
let audio;function beep(f){if(muted)return;try{audio||(audio=new (window.AudioContext||window.webkitAudioContext)());let o=audio.createOscillator(),g=audio.createGain();o.frequency.value=f;o.connect(g);g.connect(audio.destination);g.gain.setValueAtTime(.035,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+.12);o.start();o.stop(audio.currentTime+.12)}catch{}}
function move(dir){if(mode==='play')targetLane=Math.max(0,Math.min(2,targetLane+dir))}function jump(){if(mode==='play'&&jumpY===0){vy=520;beep(380)}}
function loop(t){let dt=Math.min(.033,(t-last)/1000||0);last=t;drawMountain();drawTrack();for(let tr of trees)drawTree(tr);let sorted=[...objects].sort((a,b)=>b.z-a.z);for(let o of sorted){if(o.type==='coin')drawCoin(o);else if(o.type==='rock')drawRock(o);else drawGate(o)}rider();update(dt);requestAnimationFrame(loop)}requestAnimationFrame(loop);
document.getElementById('leftBtn').ontouchstart=e=>{e.preventDefault();move(-1)};document.getElementById('rightBtn').ontouchstart=e=>{e.preventDefault();move(1)};document.getElementById('jumpBtn').ontouchstart=e=>{e.preventDefault();jump()};addEventListener('keydown',e=>{if(e.key==='ArrowLeft'||e.key==='a')move(-1);if(e.key==='ArrowRight'||e.key==='d')move(1);if(e.key===' '||e.key==='ArrowUp'||e.key==='w')jump();if(e.key==='Escape')togglePause()});
document.getElementById('pauseBtn').onclick=togglePause;function togglePause(){if(mode==='play'){mode='pause';pausePanel.classList.remove('hidden');controls.classList.add('hidden')}else if(mode==='pause'){mode='play';pausePanel.classList.add('hidden');controls.classList.remove('hidden')}}document.getElementById('resumeBtn').onclick=togglePause;document.getElementById('quitBtn').onclick=()=>location.reload();document.getElementById('restartBtn').onclick=start;document.getElementById('logoutBtn').onclick=()=>location.reload();document.getElementById('soundBtn').onclick=e=>{muted=!muted;e.currentTarget.textContent=muted?'×':'♪'};
